C='#262626'; M='#686868'; B='#bdbdbd'; F='#f2f2f2'
def t(x,y,s,size=18,weight=400,color=C):
 return f'<text x="{x}" y="{y}" font-family="Arial, sans-serif" font-size="{size}" font-weight="{weight}" fill="{color}">{escape(s)}</text>'
def r(x,y,w,h,fill='white',stroke=B): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="4" fill="{fill}" stroke="{stroke}"/>'
def line(x,y,x2,y2): return f'<path d="M{x} {y} L{x2} {y2}" fill="none" stroke="{B}"/>'
def btn(x,y,s,w=150,primary=False): return r(x,y,w,40,C if primary else 'white')+t(x+14,y+26,s,16,500,'white' if primary else C)
def field(x,y,label,value,w=500):return t(x,y,label,16,500)+r(x,y+12,w,44)+t(x+14,y+40,value,17,400,M)
def lines(x,y,ss,size=18,step=30):return ''.join(t(x,y+i*step,s,size) for i,s in enumerate(ss))
def box(x,y,w,h,title,ss=[]):return r(x,y,w,h)+t(x+20,y+34,title,20,600)+lines(x+20,y+72,ss,17)
